), u AS (
  UPDATE alu_profiles p SET image_path = v.path
  FROM v WHERE p.id = v.id AND p.tenant_id = '1b9affc4-2136-4ed1-b168-a36e6624e743' AND p.image_path IS NULL
  RETURNING p.id
)
SELECT count(*) AS updated FROM u;
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM alu_profiles WHERE tenant_id = '1b9affc4-2136-4ed1-b168-a36e6624e743' AND image_path LIKE '1b9affc4-2136-4ed1-b168-a36e6624e743/profiles/%';
  IF n <> 3046 THEN RAISE EXCEPTION 'expected 3046 profiles with an image, got %', n; END IF;
END $$;
COMMIT;
